messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: two cars race on a straight track toward a visible finish line. One car is bright RED, the other bright BLUE. The blue car leads early, then the red car accelerates, overtakes mid-race, and wins. After the red car crosses the finish line the race resets and loops forever. Both cars must be clearly visible and large enough to follow throughout (fill a meaningful part of the frame). Simple ground and sky, camera keeps both cars in view. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>3D Car Race</title>
    <style>
        body { margin: 0; overflow: hidden; }
        canvas { display: block; }
    </style>
</head>
<body>
    <script type="module">
        import * as THREE from './three.module.js';

        // Scene setup
        const scene = new THREE.Scene();
        const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        document.body.appendChild(renderer.domElement);

        // Lighting
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
        scene.add(ambientLight);
        const directionalLight = new THREE.DirectionalLight(0xffffff, 0.6);
        directionalLight.position.set(5, 10, 7);
        scene.add(directionalLight);

        // Ground (plane)
        const groundGeometry = new THREE.PlaneGeometry(200, 10);
        const groundMaterial = new THREE.MeshStandardMaterial({ color: 0xcccccc });
        const ground = new THREE.Mesh(groundGeometry, groundMaterial);
        ground.rotation.x = -Math.PI / 2;
        ground.position.y = -0.01;
        scene.add(ground);

        // Finish line (vertical plane)
        const finishLineGeometry = new THREE.PlaneGeometry(200, 0.5);
        const finishLineMaterial = new THREE.MeshStandardMaterial({ color: 0x00ff00 });
        const finishLine = new THREE.Mesh(finishLineGeometry, finishLineMaterial);
        finishLine.rotation.x = Math.PI / 2;
        finishLine.position.z = 0;
        scene.add(finishLine);

        // Car models (simple boxes for demonstration)
        const carSize = 2;
        const redCarGeometry = new THREE.BoxGeometry(carSize, carSize * 0.5, carSize * 1.5);
        const redCarMaterial = new THREE.MeshStandardMaterial({ color: 0xff0000 });
        const redCar = new THREE.Mesh(redCarGeometry, redCarMaterial);
        redCar.position.set(-80, carSize * 0.25, 0);

        const blueCarGeometry = new THREE.BoxGeometry(carSize, carSize * 0.5, carSize * 1.5);
        const blueCarMaterial = new THREE.MeshStandardMaterial({ color: 0x0000ff });
        const blueCar = new THREE.Mesh(blueCarGeometry, blueCarMaterial);
        blueCar.position.set(-100, carSize * 0.25, 0);

        // Add cars to scene
        scene.add(redCar);
        scene.add(blueCar);

        // Camera position
        camera.position.set(0, 20, 100);
        camera.lookAt(0, 0, 0);

        // Animation variables
        const carSpeed = 0.02; // Base speed
        let redAcceleration = 0; // Will increase as race progresses
        const finishLinePosition = 0; // Z position of finish line

        // Reset function to restart race
        function resetRace() {
            // Reset positions
            redCar.position.set(-80, carSize * 0.25, 0);
            blueCar.position.set(-100, carSize * 0.25, 0);
            // Reset speeds (blue leads initially)
            redAcceleration = 0;
        }

        // Start the race
        resetRace();

        // Animation loop
        function animate() {
            requestAnimationFrame(animate);

            // Update car speeds: blue leads early, red accelerates
            const time = performance.now() * 0.001;
            redAcceleration = Math.sin(time * 2) * 0.02; // Oscillating acceleration for red car

            // Move cars forward (Z-axis)
            blueCar.position.z += carSpeed + redAcceleration;
            redCar.position.z += carSpeed + redAcceleration;

            // Check if red car has crossed finish line (z >= 0)
            if (redCar.position.z >= finishLinePosition) {
                // Reset race immediately
                resetRace();
            }

            // Keep both cars in view (camera follows)
            const maxDistance = Math.max(Math.abs(blueCar.position.z), Math.abs(redCar.position.z));
            camera.position.z = maxDistance + 50;

            renderer.render(scene, camera);
        }

        // Handle window resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        // Start animation
        animate();
    </script>
</body>
</html>
```
